def affected(l) -> bool:
    # Mutant range(min, max) never ends at max, so for non-empty l it always returns False.
    # Original returns True only for non-empty integer lists with no duplicates that form a consecutive run.
    # Empty l raises ValueError in both versions; non-integer lists raise TypeError in both.
    if not isinstance(l, (list, tuple)) or len(l) == 0:
        return False
    if not all(isinstance(x, int) for x in l):
        return False
    return len(set(l)) == len(l) and max(l) - min(l) + 1 == len(l)
